import { Bell, ChevronDown } from "lucide-react";

function TopBar() {
  const today = new Date()
    .toLocaleDateString("en-US", {
      weekday: "long",
      month: "long",
      day: "numeric",
      year: "numeric",
    })
    .toUpperCase();

  return (
    <header className="flex items-center justify-between px-8 lg:px-14 h-24 bg-cream border-b border-slate-200 sticky top-0 z-10">
      <p className="font-mono text-sm tracking-widest text-slate-500">
        {today}
      </p>

      <div className="flex items-center gap-6">
        <button className="relative text-slate-600 hover:text-ink transition-colors">
          <Bell size={24} strokeWidth={1.8} />
          <span className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-brand border-2 border-cream" />
        </button>

        <button className="flex items-center gap-3">
          <span className="w-10 h-10 rounded-full bg-brand/20 text-brand text-sm font-semibold flex items-center justify-center">
            KS
          </span>
          <span className="font-semibold">Krisha</span>
          <ChevronDown size={16} className="text-slate-500" />
        </button>
      </div>
    </header>
  );
}

export default TopBar;
